{
  "$schema": "https://json.schemastore.org/package.json",
  "name": "@glaicer/supercode-token-usage-panel",
  "version": "1.4.1",
  "description": "OpenCode TUI sidebar section: cumulative token usage and cost of the current session family.",
  "type": "module",
  "license": "MIT",
  "author": "Dmitrii Aronov <aronov.mml@gmail.com>",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Glaicer/supercode-token-usage-panel.git"
  },
  "homepage": "https://github.com/Glaicer/supercode-token-usage-panel#readme",
  "bugs": "https://github.com/Glaicer/supercode-token-usage-panel/issues",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "tui-plugin",
    "token-usage",
    "token-cost",
    "generation-speed"
  ],
  "exports": {
    ".": "./dist/index.js",
    "./server": "./dist/index.js",
    "./tui": "./dist/usage-panel.js"
  },
  "files": [
    "dist",
    "index.ts",
    "tui.js"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "check:package": "node scripts/check-package.mjs",
    "prepack": "npm run build && npm run check:package",
    "test": "node --test --conditions browser 'src/**/*.test.ts'",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@opencode/plugin": ">=2.0.16"
  },
  "peerDependencies": {
    "@opentui/core": ">=0.5.10",
    "@opentui/solid": ">=0.5.10",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@babel/core": "7.28.0",
    "@babel/preset-typescript": "7.27.1",
    "@opencode/client": "2.0.16",
    "@opentui/core": "0.5.12",
    "@opentui/solid": "0.5.12",
    "@types/node": "24.13.3",
    "babel-preset-solid": "1.9.12",
    "solid-js": "1.9.12",
    "typescript": "5.8.2"
  },
  "engines": {
    "node": ">=24",
    "opencode": ">=2.0.0"
  }
}
